package com.moodcanvas.servlet;
import com.moodcanvas.dao.UserDAO;import com.moodcanvas.model.User;import jakarta.servlet.http.*;import java.io.*;
public class ThemeCookieServlet extends HttpServlet {private static final long serialVersionUID=1L;protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException{s.setContentType("text/plain;charset=UTF-8");String t=q.getParameter("theme");if(!"warm".equals(t)&&!"cool".equals(t)&&!"dark".equals(t)){s.sendError(400);return;}Cookie c=new Cookie("moodcanvas_theme",t);c.setMaxAge(2592000);c.setPath(q.getContextPath().isEmpty()?"/":q.getContextPath());c.setHttpOnly(false);s.addCookie(c);HttpSession x=q.getSession(false);if(x!=null&&x.getAttribute("user") instanceof User u)try{new UserDAO().updateTheme(u.getUserID(),t);x.setAttribute("theme",t);}catch(Exception ignored){}s.getWriter().write("OK");}}
